package org.lira.receiver;
import org.json.*;import java.io.*;import java.nio.file.*;
public final class DictationPoliciesTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception {JSONObject original=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8"));
 for(String anchor:new String[]{"after_playback","from_item_start"})for(String resume:new String[]{"remaining","restart_current"}){JSONObject task=new JSONObject(original.toString());task.getJSONObject("parameters").put("expanded_timer_anchor",anchor).put("resume_timer_policy",resume).put("expanded_word_seconds",10);File dir=Files.createTempDirectory("policies").toFile();TaskAssetStore assets=new TaskAssetStore(new File(dir,"a"));DictationEngineTest.Time time=new DictationEngineTest.Time();DictationEngineTest.Sound sound=new DictationEngineTest.Sound();DictationEngine e=new DictationEngine(time,sound,new DictationEngine.Display(){public void show(String k,JSONArray w,String t){}},new DictationStateStore(new File(dir,"s")),assets);e.start(DictationCompletionTest.prepare(task,assets));sound.drain();check(sound.repeats==3,"repeat count owned by television");time.t+=3000;sound.drain();time.t+=2000;e.control(DictationEngineTest.command(e,"pause"));e.control(DictationEngineTest.command(e,"continue"));sound.drain();long wait=resume.equals("restart_current")?10000:anchor.equals("from_item_start")?5000:8000;int index=e.status().getInt("index");time.t+=wait-1;e.tick();check(e.status().getInt("index")==index,"resume not early");time.t++;e.tick();check(e.status().getInt("index")==index+1,"resume timer policy");}
 JSONObject task=new JSONObject(original.toString());task.getJSONObject("parameters").put("advance_mode","manual");File dir=Files.createTempDirectory("manual").toFile();TaskAssetStore assets=new TaskAssetStore(new File(dir,"a"));DictationEngineTest.Time time=new DictationEngineTest.Time();DictationEngineTest.Sound sound=new DictationEngineTest.Sound();DictationEngine e=new DictationEngine(time,sound,new DictationEngine.Display(){public void show(String k,JSONArray w,String t){}},new DictationStateStore(new File(dir,"s")),assets);e.start(DictationCompletionTest.prepare(task,assets));sound.drain();DictationEngine.Completion completion=sound.done;completion.done(false);check(e.status().getString("state").equals("paused"),"audio failure pauses");check(e.status().getJSONArray("counted").length()==0,"audio failure never counts");e.control(DictationEngineTest.command(e,"continue"));sound.drain();time.t+=999999;e.tick();check(e.status().getInt("index")==1,"manual never advances from timer");JSONObject stale=DictationEngineTest.command(e,"next");stale.put("expected_state_revision",1);try{e.control(stale);throw new AssertionError("stale accepted");}catch(IllegalArgumentException expected){}e.control(DictationEngineTest.command(e,"next"));check(e.status().getInt("index")==2,"manual next after audio");System.out.println("Dictation timer anchors, resume policies, repeats, manual, audio failure, stale controls passed");}
}
